const { log, i18n, events, exec, util } = require("@node-red/util");
const { v4: uuidv } = require('uuid')

var runtime;
function init(_runtime) {
    log.info("[CAUSEWAY] initialized causeway runtime ")
    console.log("length of runtime keys ", Object.keys(_runtime).length)
    console.log(Object.keys(_runtime))
    runtime = _runtime
}

async function getContext() {
    let ctx = runtime.nodes.getContext('global')
    return ctx
}

module.exports = {
    init: init,
    getContext: getContext,
}